CREATE TABLE workspaces (id uuid PRIMARY KEY, slug text NOT NULL UNIQUE, name text NOT NULL, settings_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, display_name text NOT NULL, password_hash text, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('owner','editor','viewer')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,user_id));
CREATE TABLE objects (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, kind text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, UNIQUE(workspace_id,id));
CREATE INDEX objects_workspace_kind_idx ON objects(workspace_id,kind) WHERE deleted_at IS NULL;
CREATE TABLE sessions (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash bytea NOT NULL UNIQUE, expires_at timestamptz NOT NULL, last_used_at timestamptz NOT NULL DEFAULT now(), user_agent text, ip_hash bytea, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_expires_idx ON sessions(user_id,expires_at);
CREATE TABLE webauthn_credentials (id bytea PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, credential_json jsonb NOT NULL, name text NOT NULL DEFAULT 'Passkey', created_at timestamptz NOT NULL DEFAULT now(), last_used_at timestamptz);
CREATE TABLE webauthn_ceremonies (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('registration','login')), session_json jsonb NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, aggregate_id uuid NOT NULL, aggregate_type text NOT NULL, type text NOT NULL, payload_version integer NOT NULL DEFAULT 1, payload jsonb NOT NULL, available_at timestamptz NOT NULL, dispatched_at timestamptz, attempts integer NOT NULL DEFAULT 0, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_pending_idx ON outbox_events(available_at) WHERE dispatched_at IS NULL;
CREATE TABLE jobs (id uuid PRIMARY KEY, workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE, queue text NOT NULL, type text NOT NULL, idempotency_key text NOT NULL UNIQUE, payload_version integer NOT NULL DEFAULT 1, payload jsonb NOT NULL, state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','running','retry_wait','succeeded','dead')), priority integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL, lease_owner text, lease_until timestamptz, attempts integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 8, last_error_code text, detail_ref text, traceparent text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_claim_idx ON jobs(queue,state,available_at,priority DESC);
CREATE TABLE audit_entries (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, actor_id uuid REFERENCES users(id) ON DELETE SET NULL, action text NOT NULL, target_object_id uuid, before_ref jsonb, after_ref jsonb, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_workspace_created_idx ON audit_entries(workspace_id,created_at DESC);
